mapper.select:
SELECT G.GATE_ID AS gateId, G.AIRPORT_ID AS airportId, A.AIRPORT_NAME AS airportName, A.IATA_CODE AS iataCode, G.GATE_CODE AS gateCode, G.GATE_AREA_ID AS gateAreaId, GA.AREA_NAME AS areaName, G.FLIGHT_TYPE AS flightType, G.IS_ACTIVE AS isActive FROM GATE G JOIN AIRPORT A ON G.AIRPORT_ID = A.AIRPORT_ID JOIN GATE_AREA GA ON G.GATE_AREA_ID = GA.GATE_AREA_ID
AND G.AIRPORT_ID = #{airportId}
AND G.GATE_AREA_ID = #{gateAreaId}
AND G.FLIGHT_TYPE = #{flightType}
AND G.IS_ACTIVE = #{isActive}
ORDER BY A.IATA_CODE, G.GATE_CODE

SELECT COUNT(*) 
FROM GATE 
WHERE AIRPORT_ID = #{airportId} 
  AND GATE_CODE = #{gateCode}

mapper.insert:
INSERT INTO GATE (
    AIRPORT_ID, GATE_CODE, GATE_AREA_ID, FLIGHT_TYPE, IS_ACTIVE
) VALUES (
    #{airportId}, #{gateCode}, #{gateAreaId}, #{flightType}, 'Y'
)

mapper.select:
SELECT GATE_ID AS gateId, AIRPORT_ID AS airportId, GATE_CODE AS gateCode 
FROM GATE 
WHERE GATE_ID = #{gateId}

mapper.update:
UPDATE GATE
SET GATE_CODE = #{gateCode},
    GATE_AREA_ID = #{gateAreaId},
    FLIGHT_TYPE = #{flightType}
WHERE GATE_ID = #{gateId}

UPDATE GATE
SET IS_ACTIVE = #{isActive}
WHERE GATE_ID = #{gateId}
